import React, { useState } from "react";

export default function Students() {

  const [selectedStudent, setSelectedStudent] = useState(null);

  const students = [

    {
      id: 1,
      name: "Bhagya Lakshmi",
      email: "bhagya@gmail.com",
      course: "Java Full Stack",
      progress: "85%",
      status: "Active"
    },

    {
      id: 2,
      name: "Sai Kumar",
      email: "sai@gmail.com",
      course: "React JS",
      progress: "75%",
      status: "Active"
    },

    {
      id: 3,
      name: "Priya",
      email: "priya@gmail.com",
      course: "PostgreSQL",
      progress: "92%",
      status: "Completed"
    }

  ];

  return (

    <div

      style={{

        minHeight:"100vh",

        background:

        "linear-gradient(135deg,#0f172a,#1e293b,#334155)",

        padding:"40px"

      }}

    >

      <h1

        style={{

          textAlign:"center",

          color:"white",

          fontSize:"45px"

        }}

      >

        Instructor Students

      </h1>


      <p

        style={{

          textAlign:"center",

          color:"#cbd5e1",

          marginBottom:"40px"

        }}

      >

        Manage and Track Student Performance

      </p>



      <div

        style={{

          background:"white",

          borderRadius:"20px",

          padding:"25px",

          boxShadow:

          "0 10px 30px rgba(0,0,0,0.2)"

        }}

      >

        <table

          style={{

            width:"100%",

            borderCollapse:"collapse"

          }}

        >

          <thead>

            <tr>

              <th style={th}>ID</th>

              <th style={th}>Name</th>

              <th style={th}>Email</th>

              <th style={th}>Course</th>

              <th style={th}>Progress</th>

              <th style={th}>Status</th>

              <th style={th}>Action</th>

            </tr>

          </thead>



          <tbody>

            {

              students.map((student)=>(

                <tr key={student.id}>

                  <td style={td}>

                    {student.id}

                  </td>


                  <td style={td}>

                    {student.name}

                  </td>


                  <td style={td}>

                    {student.email}

                  </td>


                  <td style={td}>

                    {student.course}

                  </td>


                  <td style={td}>

                    {student.progress}

                  </td>


                  <td style={td}>

                    <span

                      style={{

                        background:

                        student.status==="Active"

                        ? "#22c55e"

                        : "#3b82f6",

                        color:"white",

                        padding:

                        "7px 15px",

                        borderRadius:

                        "20px"

                      }}

                    >

                      {student.status}

                    </span>

                  </td>



                  <td style={td}>

                    <button

                      style={viewBtn}

                      onClick={()=>

                      setSelectedStudent(student)

                      }

                    >

                      View

                    </button>

                  </td>

                </tr>

              ))

            }

          </tbody>

        </table>

      </div>



      {

        selectedStudent &&

        <div

          style={detailBox}

        >

          <h2>

            Student Details

          </h2>

          <hr />



          <p>

            <b>Name :</b>

            {selectedStudent.name}

          </p>



          <p>

            <b>Email :</b>

            {selectedStudent.email}

          </p>



          <p>

            <b>Course :</b>

            {selectedStudent.course}

          </p>



          <p>

            <b>Progress :</b>

            {selectedStudent.progress}

          </p>



          <p>

            <b>Status :</b>

            {selectedStudent.status}

          </p>



          <button

            style={closeBtn}

            onClick={()=>

            setSelectedStudent(null)

            }

          >

            Close

          </button>

        </div>

      }

    </div>

  );

}



const th={

background:"#2563eb",

color:"white",

padding:"15px"

};



const td={

padding:"15px",

textAlign:"center",

borderBottom:

"1px solid #e2e8f0"

};



const viewBtn={

background:"#8b5cf6",

color:"white",

border:"none",

padding:"10px 18px",

borderRadius:"10px",

cursor:"pointer"

};



const closeBtn={

background:"#ef4444",

color:"white",

border:"none",

padding:"10px 18px",

borderRadius:"10px",

cursor:"pointer",

marginTop:"20px"

};



const detailBox={

background:"white",

marginTop:"40px",

padding:"30px",

borderRadius:"20px",

boxShadow:

"0 10px 25px rgba(0,0,0,0.2)"

};
